inner_grid = [row[1:14] for row in grid]

# Map cells to regions (1-indexed like I did before)
visited = [[False for _ in range(13)] for _ in range(14)]
region_map = {}
current_region = 0

def find_region(r, c):
    global current_region
    if (r, c) in region_map:
        return region_map[(r, c)]

    if inner_grid[r][c] != 0:
        return None

    current_region += 1
    region_map[(r, c)] = current_region
    stack = [(r, c)]
    while stack:
        cr, cc = stack.pop()
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = cr + dr, cc + dc
            if 0 <= nr < 14 and 0 <= nc < 13 and inner_grid[nr][nc] == 0:
                if (nr, nc) not in region_map:
                    region_map[(nr, nc)] = current_region
                    stack.append((nr, nc))
    return current_region

# Build output grid
output = []
for r in range(14):
    row = []
    for c in range(13):
        if inner_grid[r][c] == 3:
            row.append(3)  # Keep background as 3
        else:
            row.append(find_region(r, c))
    output.append(row)

print("Proposed output (region-indexed):")
for row in output:
    print(row)

# Actually, let me also consider if the output should just be the count
print("\n\nNumber of regions of 0:", current_region)

